public class AzureBlobAttachmentProvider : IFileAttachmentProvider
{
    private readonly BlobContainerClient _containerClient;

    public async Task<FileChunkResult> UploadChunkAsync(
        FileChunkData chunk, 
        IProgress<double> progress, 
        CancellationToken ct = default)
    {
        // Handle chunked upload to Azure Blob Storage
        var blobClient = _containerClient.GetBlobClient(chunk.FileId);
        // ... implementation
        return new FileChunkResult { Success = true };
    }

    public async Task<bool> DeleteAsync(string fileId, CancellationToken ct = default)
    {
        var blobClient = _containerClient.GetBlobClient(fileId);
        return await blobClient.DeleteIfExistsAsync(ct);
    }

    public async Task<string?> GetDownloadUrlAsync(string fileId, CancellationToken ct = default)
    {
        var blobClient = _containerClient.GetBlobClient(fileId);
        return blobClient.GenerateSasUri(BlobSasPermissions.Read, 
            DateTimeOffset.UtcNow.AddHours(1)).ToString();
    }
}

public class FontAwesomeProvider : IIconProvider
{
    public string? GetIconSvg(string name, string? cssClass = null)
    {
        // Return FontAwesome SVG or null to fall back to other providers
        return name switch
        {
            "user" => "<svg class=\"" + cssClass + "\" ...>...</svg>",
            "search" => "<svg class=\"" + cssClass + "\" ...>...</svg>",
            _ => null
        };
    }

    public bool HasIcon(string name) => 
        name is "user" or "search" or "home";
}

// Program.cs
